<?php
require dirname(__DIR__) . '/_init.php';
$status=query('status'); $search=substr(query('q'),0,100); $result=Contact::listing(max(1,(int)query('page','1')),$status,$search);
admin_start('Conversations start here.','contacts','Enquiries sent through your website contact form.');
?>
<form class="flex flex-col sm:flex-row gap-3 mb-6" method="get"><label class="sr-only" for="q">Search messages</label><input id="q" name="q" type="search" placeholder="Search names, emails or messages…" value="<?= e($search) ?>" maxlength="100" class="sm:max-w-md"><label class="sr-only" for="status">Filter by status</label><select name="status" id="status" class="sm:max-w-48"><?php foreach([''=>'All messages','new'=>'New','read'=>'Read','archived'=>'Archived'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $status===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select><button type="submit" class="btn btn-primary">Filter</button></form><section class="card overflow-hidden"><div class="overflow-x-auto"><table class="admin-table"><thead><tr><th scope="col">From</th><th scope="col">Interested in</th><th scope="col">Received</th><th scope="col">Status</th><th scope="col">Message</th></tr></thead><tbody><?php foreach($result['items'] as $item): ?><tr><td><p class="font-semibold"><?= e($item['name']) ?></p><p class="text-xs text-muted"><?= e($item['email']) ?></p></td><td><?= e($item['service']?:'General enquiry') ?></td><td class="whitespace-nowrap"><?= e(date('M j, Y',strtotime($item['created_at']))) ?></td><td><?= badge($item['status']) ?></td><td><a class="link-arrow" href="<?= e(url('admin/contacts/view.php?id='.$item['id'])) ?>">Open <?= icon('arrow','w-4 h-4') ?></a></td></tr><?php endforeach ?><?php if(!$result['items']): ?><tr><td colspan="5" class="text-center text-muted py-10">No messages match this view.</td></tr><?php endif ?></tbody></table></div></section><p class="text-sm text-muted mt-4"><?= $result['total'] ?> messages</p><?php view('layouts/pagination',['page'=>$result['page'],'pages'=>$result['pages'],'paginationUrl'=>url('admin/contacts/index.php'),'paginationParams'=>['status'=>$status,'q'=>$search]]); admin_end(); ?>
